/* بيانات باب ijaz: تُحمَّل عند أول فتح للقسم */
window.IJAZ = {"ch":[{"id":"kawn","t":"الكون والفلك","d":"آيات في نشأة السماء وحركة الشمس والقمر والنجوم واتساع الكون وما فيها من تقدير وإحكام."},{"id":"ard","t":"الأرض والجبال والمياه الجوفية","d":"آيات في الجبال والأرض الهامدة إذا نزل عليها المطر، وما أودعه الله في باطنها من مياه، وموضع المعركة في «أدنى الأرض»."},{"id":"bahr","t":"البحار والسحاب والمطر والماء","d":"آيات في البحرين والحاجز بينهما وظلمات البحر، وتكوّن السحاب والمطر وتلقيح الرياح، والماء أصلاً للحياة."},{"id":"insan","t":"خلق الإنسان والأجنة","d":"آيات في أطوار خلق الإنسان في الرحم ونطفته وحواسه، وما قيل فيها من قراءات علمية معاصرة."},{"id":"ahya","t":"الأحياء: النحل والزوجية","d":"آيات في النحل وبيوتها وعسلها، وفي أن الخلق أزواج."}],"tp":[{"id":"ratq","ch":"kawn","t":"الرتق والفتق","e":"الآية في السماء والأرض حين كانتا رتقاً ثم فُتقتا، وما قاله المفسرون في معنى الرتق والفتق.","lv":"x","ay":[[21,30,30]],"q":[{"bk":"ibnkathir","s":21,"ay":30,"x":"فقال ابن عباس: نعم، كانت السموات رَتْقًا لَا تُمْطِرُ، وَكَانَتْ الْأَرْضُ رَتْقًا لَا تُنْبِتُ.","w":"ابن كثير","en":"Ibn Abbas said: yes, the heavens were joined together and did not rain, and the earth was joined together and did not sprout."},{"bk":"al-muharrar-al-wajiz-ibn-atiyyah","s":21,"ay":30,"x":"وقالَتْ فِرْقَةٌ: السَماءُ قَبْلَ المَطَرِ رَتْقٌ، والأرْضُ قَبْلَ النَباتِ رَتْقٌ، فَفَتَقَهُما اللهُ تَعالى بِالمَطَرِ والنَباتِ، كَما قالَ اللهُ تَبارَكَ وتَعالى: ﴿والسَماءِ ذاتِ الرَجْعِ﴾ [الطارق: ١١] ﴿والأرْضِ ذاتِ الصَدْعِ﴾ [الطارق: ١٢]، وهَذا قَوْلٌ حَسَنٌ يَجْمَعُ العِبْرَةَ وتَعْدِيدَ النِعْمَةِ والحُجَّةَ بِمَحْسُوسٍ بَيِّنٍ، ويُناسِبُ قَوْلَهُ تَعالى: ﴿وَجَعَلْنا مِنَ الماءِ كُلَّ شَيْءٍ حَيٍّ﴾، أيْ: مِنَ الماءِ الَّذِي أوجَدَهُ الفَتْقُ، فَيَظْهَرُ مَعْنى الآيَةِ ويَتَوَجَّهُ الِاعْتِبارُ.","w":"ابن عطية","en":"Another group said: the sky before rain was a joined mass and the earth before vegetation was a joined mass, so Allah split them by rain and vegetation, as He said, \"By the sky that gives back\" and \"by the earth that splits\". This is a good view, combining the lesson, the counting of the favour and the proof from the plainly visible, and it fits His words \"and We made from water every living thing\", meaning the water the splitting brought forth, so the verse's meaning is clear and the lesson follows.","bt":"المحرر الوجيز لابن عطية"},{"bk":"tafsir-al-razi","s":21,"ay":30,"x":"وثانِيًا: أنْ يُحْمَلَ الرَّتْقُ والفَتْقُ عَلى إمْكانِ الرَّتْقِ والفَتْقِ، والعَقْلُ يَدُلُّ عَلَيْهِ لِأنَّ الأجْسامَ يَصِحُّ عَلَيْها الِاجْتِماعُ والِافْتِراقُ فاخْتِصاصُها بِالِاجْتِماعِ دُونَ الِافْتِراقِ أوْ بِالعَكْسِ يَسْتَدْعِي مُخَصِّصًا.","w":"الرازي","en":"Second: that the joining and parting be taken as the possibility of joining and parting, which reason indicates, since bodies can be joined or separated, so assigning them to joining and not parting, or the reverse, calls for One who assigns.","bt":"مفاتيح الغيب (التفسير الكبير) للرازي"}],"h":[],"sci":"تدل الرصودات الفلكية (تباعد المجرات والإشعاع الكوني الخلفي) على أن الكون الملاحَظ كان قبل نحو ١٣٫٨ مليار سنة في حالة شديدة الكثافة والحرارة ثم أخذ يتمدد ويبرد، وهو ما يُعرف بنموذج الانفجار العظيم.","note":"ربط الآية بنشأة الكون اجتهاد معاصر. فالمأثور عن ابن عباس أن السماء كانت لا تمطر والأرض لا تنبت (ابن كثير)، وفي الطبري عنه أيضاً: «كانتا ملتصقتين»، وعدّ ابن عطية القول بالمطر والنبات «قولاً حسناً»، وذكر الرازي أن الآية تحتمل إمكان الاجتماع والافتراق. فلا يُجزم بأن المراد نشأة الكون.","refs":["Planck Collaboration, «Planck 2018 results. VI. Cosmological parameters», Astronomy & Astrophysics 641, A6 (2020)."]},{"id":"dukhan","ch":"kawn","t":"السماء دخان","e":"الآية في استواء الله إلى السماء وهي دخان قبل أن يقضيها سبع سماوات.","lv":"x","ay":[[41,11,11]],"q":[{"bk":"ibnkathir","s":41,"ay":11,"x":"وَقَوْلُهُ: ﴿ثُمَّ اسْتَوَى إِلَى السَّمَاءِ وَهِيَ دُخَانٌ﴾ ، وَهُوَ: بُخَارُ الماء المتصاعد منه حين خلقت الأرض، ﴿فَقَالَ لَهَا وَلِلأرْضِ اِئْتِيَا طَوْعًا أَوْ كَرْهًا﴾ أَيِ: اسْتَجِيبَا لِأَمْرِي، وَانْفَعِلَا لِفِعْلِي طَائِعَتَيْنِ أَوْ مُكْرَهَتَيْنِ.","w":"ابن كثير","en":"And His words \"then He turned to the heaven while it was smoke\": that is the water vapour that rose from it when the earth was created; \"and said to it and to the earth: come, willingly or unwillingly\", meaning respond to My command and be acted upon as I act, obedient or compelled."},{"bk":"qurtubi","s":41,"ay":11,"x":"وَ \"ثُمَّ\" تَرْجِعُ إِلَى نَقْلِ السَّمَاءِ مِنْ صِفَةِ الدُّخَانِ إِلَى حَالَةِ الْكَثَافَةِ، وَكَانَ ذَلِكَ الدُّخَانُ مِنْ تَنَفُّسِ الْمَاءِ حِينَ تَنَفَّسَ، عَلَى مَا مَضَى فِي [الْبَقَرَةِ] عَنِ ابْنِ مَسْعُودٍ وَغَيْرِهِ.","w":"القرطبي","en":"And \"then\" returns to moving the heaven from the state of smoke to the state of density; that smoke was from the breathing of the water when it breathed, as mentioned in al-Baqarah from Ibn Masud and others."}],"h":[],"sci":"كان الكون المبكر غازاً حاراً مؤيَّناً أغلبه هيدروجين وهيليوم، ومنه تكوّنت النجوم والمجرات لاحقاً بفعل الجاذبية؛ ولا تزال سحب الغاز والغبار الكونية (السُّدُم) مهداً لولادة النجوم.","note":"قال ابن كثير إن الدخان بخار الماء المتصاعد حين خُلقت الأرض، ونقل القرطبي أنه من تنفس الماء عن ابن مسعود وغيره. فربط الدخان بالحالة الغازية الأولى للكون اجتهاد معاصر، والآية في ترتيب خلق الأرض والسماء الذي اختلف فيه المفسرون.","refs":["Planck Collaboration, «Planck 2018 results. VI. Cosmological parameters», Astronomy & Astrophysics 641, A6 (2020)."]},{"id":"insaa","ch":"kawn","t":"«وإنا لموسعون»","e":"الآية في بناء السماء بقوة وأنه تعالى موسِّع لها.","lv":"m","ay":[[51,47,47]],"q":[{"bk":"ibnkathir","s":51,"ay":47,"x":"قَالَهُ ابْنُ عَبَّاسٍ، وَمُجَاهِدٌ، وقَتَادَةُ، وَالثَّوْرِيُّ، وَغَيْرُ وَاحِدٍ، ﴿وَإِنَّا لَمُوسِعُونَ﴾ ، أَيْ: قَدْ وَسَّعْنَا أَرْجَاءَهَا وَرَفَعْنَاهَا بِغَيْرِ عَمِدٍ، حَتَّى اسْتَقَلَّتْ كَمَا هِيَ.","w":"ابن كثير","en":"Said by Ibn Abbas, Mujahid, Qatadah, al-Thawri and many others: \"and We are its expander\", meaning We have widened its reaches and raised it without pillars until it stood as it is."},{"bk":"qurtubi","s":51,"ay":47,"x":"(وَإِنَّا لَمُوسِعُونَ) قَالَ ابْنُ عَبَّاسٍ: لَقَادِرُونَ.","w":"القرطبي","en":"\"And We are its expander\": Ibn Abbas said, \"able\"."},{"bk":"tafsir-al-razi","s":51,"ay":47,"x":"صفحة ١٩٥ وقَوْلُهُ تَعالى: ﴿وإنّا لَمُوسِعُونَ﴾ فِيهِ وُجُوهٌ: أحَدُها: أنَّهُ مِنَ السَّعَةِ أيْ أوْسَعْناها بِحَيْثُ صارَتِ الأرْضُ وما يُحِيطُ بِها مِنَ الماءِ والهَواءِ بِالنِّسْبَةِ إلى السَّماءِ وسَعَتِها كَحَلْقَةٍ في فَلاةٍ …","w":"الرازي","en":"And His words \"and indeed We are its expander\" have several readings. One is that it is from \"capacity\", that is We widened it, so that the earth and what surrounds it of water and air is, relative to the sky and its vastness, like a ring in a desert.","bt":"مفاتيح الغيب (التفسير الكبير) للرازي"}],"h":[],"sci":"أثبتت رصودات هابل (١٩٢٩م) وقبله حسابات لوميتر (١٩٢٧م) أن المجرات البعيدة تتباعد عنا، وأن الكون يتسع؛ وتؤكده قياسات المستعرات العظمى والإشعاع الكوني الخلفي، وهو مما استقر عليه علماء الفلك.","note":"فسّر المفسرون «لموسعون» بالقدرة (ابن عباس) أو بتوسعة أرجاء السماء ورفعها (ابن كثير) أو بسعة الرزق، وذكر الرازي أنه من السعة. وصيغة اسم الفاعل تحتمل الاستمرار لغةً، فمن هنا جاء الربط المعاصر باتساع الكون، وهو ربط مقبول لغةً وليس هو المأثور.","refs":["Edwin Hubble, «A relation between distance and radial velocity among extra-galactic nebulae», PNAS 15 (1929)، وGeorges Lemaître, Annales de la Société Scientifique de Bruxelles 47 (1927).","Planck Collaboration, «Planck 2018 results. VI. Cosmological parameters», Astronomy & Astrophysics 641, A6 (2020)."]},{"id":"falak","ch":"kawn","t":"«كل في فلك يسبحون»","e":"الآيات في أن الشمس والقمر وسائر الأجرام تجري كلٌّ في فلك بحساب مقدَّر.","lv":"z","ay":[[21,33,33],[36,40,40],[55,5,5]],"q":[{"bk":"ibnkathir","s":21,"ay":33,"x":"﴿وَالشَّمْسَ وَالْقَمَرَ﴾ هَذِهِ لَهَا نُورٌ يَخُصُّهَا، وَفَلَكٌ بِذَاتِهِ، وَزَمَانٌ عَلَى حِدَةٍ، وَحَرَكَةٍ وَسَيْرٍ خَاصٍّ، وَهَذَا بِنُورٍ خَاصٍّ آخَرَ، وَفَلَكٍ آخَرَ، وَسَيْرٍ آخَرَ، وَتَقْدِيرٍ آخَرَ، ﴿وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾ [يس:٤٠] ، أَيْ: يَدُورُونَ.","w":"ابن كثير","en":"The sun and the moon each have a light of its own, an orbit of its own, a time of its own, and a particular motion and course, and the other has a particular light of its own, another orbit, another course and another measure; \"each floating in an orbit\" (Ya-Sin 40), meaning they revolve."},{"bk":"qurtubi","s":21,"ay":33,"x":"(كُلٌّ) يَعْنِي مِنَ الشَّمْسِ وَالْقَمَرِ وَالنُّجُومِ وَالْكَوَاكِبِ وَاللَّيْلِ وَالنَّهَارِ (فِي فَلَكٍ يَسْبَحُونَ) أَيْ يَجْرُونَ وَيَسِيرُونَ بِسُرْعَةٍ كَالسَّابِحِ فِي الْمَاءِ.","w":"القرطبي","en":"\"Each\", meaning the sun, the moon, the stars, the planets, the night and the day, \"in an orbit they float\": they run and travel quickly like a swimmer in water."},{"bk":"ibnkathir","s":55,"ay":5,"x":"وَقَوْلُهُ: ﴿الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ﴾ أَيْ: يَجْرِيَانِ مُتَعَاقِبَيْنَ بِحِسَابٍ مُقَنَّن لَا يَخْتَلِفُ وَلَا يَضْطَرِبُ …","w":"ابن كثير","en":"And His words \"the sun and the moon by a reckoning\": they run in succession by a fixed reckoning that neither differs nor falters."}],"h":[],"sci":"لكل جرم سماوي مدار: القمر حول الأرض، والأرض والكواكب حول الشمس، والشمس نفسها حول مركز مجرة درب التبانة في نحو ٢٣٠ مليون سنة، وكلها تسير بحساب دقيق تُتوقَّع به الخسوفات والكسوفات قبل وقوعها بسنوات.","note":"المعنى هنا ظاهر عند المفسرين: لكل من الشمس والقمر فلك ومسير (ابن كثير) يجريان بحساب مقنَّن لا يختلف. أما صفة الفلك نفسه فاختلف فيها القدماء كما ذكر الرازي، فلا يلزم من الآية قول بعينه فيها.","refs":["Binney & Tremaine, Galactic Dynamics, Princeton University Press."]},{"id":"diaa","ch":"kawn","t":"الشمس ضياء والقمر نور","e":"الآية في أن الشمس ضياء والقمر نور وأن الله قدّر القمر منازل لمعرفة السنين والحساب.","lv":"m","ay":[[10,5,5],[71,15,16]],"q":[{"bk":"tafsir-al-razi","s":10,"ay":5,"x":"وإذا كانَ كَذَلِكَ وجَبَ أنْ يَكُونَ اخْتِصاصُ جِرْمِ الشَّمْسِ بِضَوْئِهِ القاهِرِ، واخْتِصاصُ القَمَرِ بِنُورِهِ الضَّعِيفِ بِتَخْصِيصِ مُخَصِّصٍ وإيجادِ مُوجِدٍ وتَقْدِيرِ مُقَدِّرٍ …","w":"الرازي","en":"This being so, the sun's being singled out for its overpowering brightness and the moon's for its weak light must be by one who singles out, brings into being and measures; and that is what was sought.","bt":"مفاتيح الغيب (التفسير الكبير) للرازي"},{"bk":"tafsir-al-razi","s":10,"ay":5,"x":"المَسْألَةُ الثّالِثَةُ: قالَ أبُو عَلِيٍّ الفارِسِيُّ: الضِّياءُ لا يَخْلُو مِن أحَدِ أمْرَيْنِ: إمّا أنْ يَكُونَ جَمْعَ ضَوْءٍ كَسَوْطٍ وسِياطٍ وحَوْضٍ وحِياضٍ، أوْ مَصْدَرَ ضاءَ يَضُوءُ ضِياءً، كَقَوْلِكَ: قامَ قِيامًا، وصامَ صِيامًا، وعَلى أيِّ الوَجْهَيْنِ حَمَلْتَهُ، فالمُضافُ مَحْذُوفٌ، والمَعْنى جَعَلَ الشَّمْسَ ذاتَ ضِياءٍ، والقَمَرَ ذا نُورٍ …","w":"الرازي","en":"Abu Ali al-Farisi said: \"diya'\" is one of two things: either the plural of \"daw'\", like \"siyat\" and \"hiyad\", or the verbal noun of \"da'a yadu'u diya'an\", like \"qama qiyaman\"; on either reading something is omitted, and the meaning is that He made the sun possessed of brightness and the moon possessed of light, or it may be otherwise, since brightness and light were so great in them that they were made brightness and light themselves, as one says of a generous man: he is generosity and bounty.","bt":"مفاتيح الغيب (التفسير الكبير) للرازي"}],"h":[],"sci":"الشمس نجم يُنتج الضوء والحرارة من الاندماج النووي في باطنه، أما القمر فجرم صخري لا يضيء بذاته ويعكس نحو ١٢٪ من ضوء الشمس الساقط عليه، ومنازله تنتج عن تغيّر موضعه بالنسبة إلى الشمس والأرض.","note":"ذكر الرازي عن أبي علي الفارسي أن «الضياء» جمع ضوء أو مصدر، وجعل اختصاص الشمس بضوئها والقمر بنوره دليلاً على من خصّص وقدّر. والتفريق العلمي بين مصدر الضوء ومنعكسه قراءة معاصرة لا نص عليها عند المفسرين، وقد وُصف القمر في القرآن بالنور وبالمنير، فلا يُجزم بأن اللفظين مقصودان للتفريق.","refs":["Binney & Tremaine, Galactic Dynamics, Princeton University Press."]},{"id":"saqf","ch":"kawn","t":"السماء سقفاً محفوظاً","e":"الآية في جعل السماء سقفاً محفوظاً.","lv":"m","ay":[[21,32,32]],"q":[{"bk":"qurtubi","s":21,"ay":32,"x":"قَوْلُهُ تَعَالَى: ﴿وَجَعَلْنَا السَّماءَ سَقْفاً مَحْفُوظاً﴾ أَيْ مَحْفُوظًا مِنْ أَنْ يَقَعَ وَيَسْقُطَ عَلَى الْأَرْضِ، دَلِيلُهُ قَوْلُهُ تَعَالَى: ﴿وَيُمْسِكُ السَّماءَ أَنْ تَقَعَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِ﴾ [الحج: ٦٥].","w":"القرطبي","en":"\"And We made the sky a protected roof\", meaning protected from falling and dropping onto the earth, as His words show: \"and He holds back the sky from falling upon the earth except by His leave\" (al-Hajj 65)."},{"bk":"qurtubi","s":21,"ay":32,"x":"وَقِيلَ: مَحْفُوظًا بِالنُّجُومِ مِنَ الشَّيَاطِينِ، قَالَهُ الْفَرَّاءُ. دَلِيلُهُ قَوْلُهُ تَعَالَى: ﴿وَحَفِظْناها مِنْ كُلِّ شَيْطانٍ رَجِيمٍ﴾ [الحجر: ١٧]. وَقِيلَ: مَحْفُوظًا مِنَ الْهَدْمِ وَالنَّقْضِ، وَعَنْ أَنْ يَبْلُغَهُ أَحَدٌ بِحِيلَةٍ.","w":"القرطبي","en":"And it was said: protected by the stars from the devils, said by al-Farra, as His words show: \"and We guarded it from every accursed devil\" (al-Hijr 17). And it was said: protected from demolition and breakage, and from anyone reaching it by trickery."}],"h":[],"sci":"يحمي الغلاف الجوي للأرض ومجالها المغناطيسي سطحها من أغلب الشهب والنيازك (تحترق بالاحتكاك)، ومن الأشعة فوق البنفسجية الضارة التي تمتصها طبقة الأوزون، ومن كثير من جسيمات الرياح الشمسية.","note":"نقل القرطبي أن «محفوظاً» أي من أن يقع ويسقط على الأرض، وقيل: بالنجوم من الشياطين، وقيل: من الهدم والنقض. وربطه بالغلاف الجوي قراءة معاصرة تجمع بين ظاهر الآية ومعنى الحفظ، وليست من المأثور.","refs":["Wallace & Hobbs, Atmospheric Science: An Introductory Survey, Academic Press."]},{"id":"takwir","ch":"kawn","t":"تكوير الليل على النهار","e":"الآية في تكوير الليل على النهار والنهار على الليل.","lv":"m","ay":[[39,5,5]],"q":[{"bk":"qurtubi","s":39,"ay":5,"x":"قَوْلُهُ تَعَالَى: ﴿يُكَوِّرُ اللَّيْلَ عَلَى النَّهارِ وَيُكَوِّرُ النَّهارَ عَلَى اللَّيْلِ﴾ قَالَ الضَّحَّاكُ: أَيْ يُلْقِي هَذَا عَلَى هَذَا وَهَذَا عَلَى هَذَا. وَهَذَا عَلَى مَعْنَى التَّكْوِيرِ فِي اللُّغَةِ وَهُوَ طَرْحُ الشَّيْءِ بَعْضُهُ عَلَى بَعْضٍ، يُقَالُ كَوَّرَ الْمَتَاعَ أَيْ أَلْقَى بَعْضَهُ على بعض، وَمِنْهُ كَوْرُ الْعِمَامَةِ.","w":"القرطبي","en":"\"He wraps the night over the day and wraps the day over the night\": al-Dahhak said, meaning He throws this over that and that over this. This accords with the meaning of \"takwir\" in the language, which is throwing things over one another; one says \"kawwara the goods\" when one throws part of them over part, and from it comes the winding of a turban."},{"bk":"saadi","s":39,"ay":5,"x":"أي: يدخِلُ كلاًّ منهما على الآخر، ويُحِلُّه محلَّه؛ فلا يجتمعُ هذا وهذا، بل إذا أتى أحدُهما؛ انعزلَ الآخر عن سلطانه، {وسخَّرَ الشمسَ والقمر}: بتسخير منظَّم وسيرٍ مقننٍ.","w":"السعدي","en":"That is, He brings each of them into the other and puts it in its place, so they do not meet; rather when one comes the other withdraws from its authority; \"and He subjected the sun and the moon\" with an ordered subjection and a measured course."}],"h":[],"sci":"تدور الأرض، وهي شبه كروية، حول محورها فيتعاقب الليل والنهار تدريجياً على كل موضع عبر الفجر والغسق، فيدخل أحدهما في الآخر ويتداخلان ولا ينفصلان فجأة.","note":"التكوير في اللغة طرح الشيء بعضه على بعض كلفّ العمامة (القرطبي)، وقال الضحاك: يلقي هذا على هذا، وفسره السعدي بإدخال كلٍّ منهما على الآخر. فالمعنى المأثور تعاقب الليل والنهار. واستنباط كروية الأرض من اللفظ احتمال لغوي لا يُجزم به، وكروية الأرض مقررة في العلم مستقلةً عن هذه الآية.","refs":["Wallace & Hobbs, Atmospheric Science: An Introductory Survey, Academic Press."]},{"id":"mustaqar","ch":"kawn","t":"«والشمس تجري لمستقر لها»","e":"الآية في أن الشمس تجري لمستقر لها.","lv":"x","ay":[[36,38,38]],"q":[{"bk":"ibnkathir","s":36,"ay":38,"x":"وَقَوْلُهُ: ﴿وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴾ ، فِي مَعْنَى قَوْلِهِ: ﴿لِمُسْتَقَرٍّ لَهَا﴾ قَوْلَانِ: أَحَدُهُمَا: أَنَّ الْمُرَادَ: مُسْتَقَرُّهَا الْمَكَانِيُّ، وَهُوَ تَحْتَ الْعَرْشِ مِمَّا يَلِي الْأَرْضَ فِي ذَلِكَ الْجَانِبِ …","w":"ابن كثير","en":"Ibn Kathir: His words \"and the sun runs to a resting place of its own\" have two views on \"its resting place\". One is that its spatial resting place is beneath the Throne on the side facing the earth on that side."},{"bk":"ibnkathir","s":36,"ay":38,"x":"وَقِيلَ: الْمُرَادُ بِقَوْلِهِ: ﴿لِمُسْتَقَرٍّ لَهَا﴾ هُوَ انْتِهَاءُ سَيْرِهَا وَهُوَ غَايَةُ ارْتِفَاعِهَا فِي السَّمَاءِ فِي الصَّيْفِ وَهُوَ أَوْجُهَا، ثُمَّ غَايَةُ انْخِفَاضِهَا فِي الشِّتَاءِ وَهُوَ الْحَضِيضُ.","w":"ابن كثير","en":"And it was said: \"its resting place\" means the end of its course, which is the height of its rise in the sky in summer, its apogee, and then the extreme of its lowering in winter, its perigee."},{"bk":"qurtubi","s":36,"ay":38,"x":"وَلَفْظُ الْبُخَارِيِّ عَنْ أَبِي ذَرٍّ قَالَ: قَالَ النَّبِيُّ ﷺ لِأَبِي ذَرٍّ حِينَ غَرَبَتِ الشَّمْسُ: \"تَدْرِي أَيْنَ تَذْهَبُ\" قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: \"فَإِنَّهَا تَذْهَبُ حَتَّى تَسْجُدَ تَحْتَ الْعَرْشِ فَتَسْتَأْذِنُ فَيُؤْذَنُ لَهَا وَيُوشِكُ أَنْ تَسْجُدَ فَلَا يُقْبَلُ مِنْهَا وَتَسْتَأْذِنَ فَلَا يُؤْذَنُ لَهَا يُقَالُ لَهَا ارْجِعِي مِنْ حَيْثُ جِئْتِ فَتَطْلُعُ مِنْ مَغْرِبِهَا فَذَلِكَ قَوْلُهُ تَعَالَى: ﴿ وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَها ذلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴾.","w":"القرطبي","en":"The wording of al-Bukhari from Abu Dharr: the Prophet, peace be upon him, said to Abu Dharr when the sun had set, \"Do you know where it goes?\" I said, \"Allah and His Messenger know best.\" He said, \"It goes until it prostrates beneath the Throne, asks leave and is given leave; but it is about to prostrate and not be accepted, and ask leave and not be given it, and be told: return from where you came; so it rises from its setting place\". The Quran verse is cited alongside."}],"h":[],"sci":"تدور الشمس حول مركز المجرة بسرعة نحو ٢٢٠ كم/ث تقريباً، وتنتقل بالنسبة إلى النجوم القريبة، وهي نجم متوسط العمر أمامه نحو خمسة مليارات سنة قبل أن يستنفد وقوده.","note":"ذكر ابن كثير في «لمستقر لها» قولين: المستقر المكاني تحت العرش، وانتهاء سيرها وغايتي ارتفاعها وانخفاضها، ونقل القرطبي حديث أبي ذر في سجودها تحت العرش، وهو من أخبار الغيب التي لا تُحمل على حركة فلكية معلومة. فهذه من مواضع الخلاف، ولا يُجزم بربط الآية بحركة الشمس في المجرة.","refs":["Binney & Tremaine, Galactic Dynamics, Princeton University Press."]},{"id":"hadid","ch":"kawn","t":"«وأنزلنا الحديد»","e":"الآية في إنزال الحديد وفيه بأس شديد ومنافع للناس.","lv":"x","ay":[[57,25,25]],"q":[{"bk":"tabari","s":57,"ay":25,"x":"وقوله: ﴿وَأَنزلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ﴾ يقول تعالى ذكره: وأنزلنا لهم الحديد فيه بأس شديد، يقول: فيه قوّة شديدة، ومنافع للناس، وذلك ما ينتفعون به منه عند لقائهم العدوّ، وغير ذلك من منافعه.","w":"الطبري","en":"And His words \"and We sent down iron, in which is great might\": He sent down iron to them, in which is great strength and benefits for people, namely what they benefit from in meeting the enemy and its other benefits."},{"bk":"saadi","s":57,"ay":25,"x":"أي: لا يعجِزُه شيءٌ ولا يفوته هاربٌ، ومن قوَّته وعزَّته أن أنزل الحديدَ الذي منه الآلاتُ القويَّة، ومن قوَّته وعزَّته أنه قادرٌ على الانتصار من أعدائه، ولكنَّه يبتلي أولياءه بأعدائه؛ ليعلم من ينصرُهُ بالغيب.","w":"السعدي","en":"That is, nothing overcomes Him and no fugitive escapes Him; and of His strength and might is that He sent down iron, from which strong tools are made, and of His strength and might is that He is able to defeat His enemies, but He tests His friends by their enemies, to know who helps Him unseen."}],"h":[],"sci":"يتكوّن الحديد بتفاعلات الاندماج النووي في قلوب النجوم الضخمة وفي انفجارات المستعرات العظمى، ثم تنثره في الفضاء فتتكون منه الكواكب؛ فحديد الأرض مما تكوّن في النجوم لا مما تكوّن على الأرض.","note":"فسّر الطبري والسعدي «أنزلنا الحديد» بما فيه من بأس شديد ومنافع للناس ولم يذكرا مصدراً كونياً. والفعل «أنزل» يُستعمل في القرآن للأنعام أيضاً ﴿وأنزل لكم من الأنعام ثمانية أزواج﴾ بمعنى الإيجاد والتهيئة، فلا يُجزم بأن المراد النزول الفلكي.","refs":["Burbidge, Burbidge, Fowler & Hoyle, «Synthesis of the Elements in Stars», Reviews of Modern Physics 29 (1957)."]},{"id":"jibal","ch":"ard","t":"الجبال أوتاداً","e":"الآيات في جعل الجبال أوتاداً ورواسي للأرض.","lv":"x","ay":[[78,6,7],[21,31,31]],"q":[{"bk":"ibnkathir","s":78,"ay":7,"x":"أَيْ: مُمَهَّدَةٌ لِلْخَلَائِقِ ذَلُولا لَهُمْ، قَارَّةً سَاكِنَةً ثَابِتَةً، ﴿وَالْجِبَالَ أَوْتَادًا﴾ أَيْ: جَعَلَهَا لَهَا أَوْتَادًا أَرْسَاهَا بِهَا وَثَبَّتَهَا وَقَرَّرَهَا حَتَّى سَكَنَتْ وَلَمْ تَضْطَرِبْ بِمَنْ عَلَيْهَا.","w":"ابن كثير","en":"\"The mountains as pegs\": He made them pegs for it, anchoring it with them and settling it until it was still and did not shake with those on it."},{"bk":"qurtubi","s":78,"ay":7,"x":"وَمَعْنَاهُ أَنَّهَا لَهُمْ كَالْمَهْدِ لِلصَّبِيِّ وَهُوَ مَا يُمَهَّدُ لَهُ فَيُنَوَّمُ عَلَيْهِ (وَالْجِبالَ أَوْتاداً) أَيْ لِتَسْكُنَ وَلَا تَتَكَفَّأَ وَلَا تَمِيلَ بِأَهْلِهَا.","w":"القرطبي","en":"It means the earth is for them like a cradle is for a child, which is prepared for him so he can sleep on it; and \"the mountains as pegs\" so that it settles, does not tilt and does not lean with its people."},{"bk":"ibnkathir","s":21,"ay":30,"x":"وَقَوْلُهُ: ﴿وَجَعَلْنَا فِي الأرْضِ رَوَاسِيَ﴾ أَيْ: جِبَالًا أَرْسَى الْأَرْضَ بِهَا وَقَرَّرَهَا وَثَقَّلَهَا؛ لِئَلَّا تَمِيدَ بِالنَّاسِ، أَيْ: تَضْطَرِبَ وَتَتَحَرَّكَ، فَلَا يَحْصُلُ لَهُمْ عَلَيْهَا قَرَارٌ لِأَنَّهَا غَامِرَةٌ فِي الْمَاءِ إِلَّا مِقْدَارَ الرُّبْعِ، فَإِنَّهُ بَادٍ لِلْهَوَاءِ وَالشَّمْسِ، لِيُشَاهِدَ أَهْلُهَا السَّمَاءَ وَمَا فِيهَا مِنَ الْآيَاتِ الْبَاهِرَاتِ، وَالْحِكَمِ وَالدَّلَالَاتِ؛ وَلِهَذَا قَالَ: ﴿أَنْ تَمِيدَ بِهِمْ﴾ أَيْ: لِئَلَّا تَمِيدَ بِهِمْ.","w":"ابن كثير","en":"And His words \"and We placed in the earth firm mountains\": mountains with which He anchored the earth, settled it and weighted it, lest it shake with the people, that is, lest it tremble and move so that they have no stability on it, since it is submerged in water except a quarter of it, which is exposed to air and sun, so its people can see the sky and its mighty signs, wisdoms and proofs; hence He said \"lest it shake with them\"."}],"h":[],"sci":"للجبال جذور من صخور أخف تمتد في قشرة الأرض أعمق بكثير من ارتفاعها فوق السطح (قاعدة الاتزان الجيولوجي، إيري ١٨٥٥م)، وتنشأ غالباً من تصادم الصفائح التكتونية.","note":"قال ابن كثير والقرطبي إنها أوتاد تثبّت الأرض فلا تضطرب بأهلها. ولا يقرر الجيولوجيون أن الجبال هي ما يمنع الزلازل، فالربط بين «أوتاداً» وجذور الجبال اجتهاد في المعنى لا يُجزم به، ولا يعارض المعنى التفسيري.","refs":["G. B. Airy, «On the computation of the effect of the attraction of mountain masses», Philosophical Transactions 145 (1855).","Kearey, Klepeis & Vine, Global Tectonics, Wiley-Blackwell."]},{"id":"adna","ch":"ard","t":"«في أدنى الأرض»","e":"الآيات في غلبة الروم في أدنى الأرض ثم ظهورهم بعد ذلك.","lv":"x","ay":[[30,2,4]],"q":[{"bk":"qurtubi","s":30,"ay":3,"x":"عِكْرِمَةُ: بِأَذْرِعَاتٍ، وَهِيَ مَا بَيْنَ بِلَادِ الْعَرَبِ وَالشَّامِ.","w":"القرطبي","en":"Ikrimah: at Adhri'at, which lies between the Arab lands and Syria."},{"bk":"qurtubi","s":30,"ay":3,"x":"و \"أَدْنَى\" مَعْنَاهُ أَقْرَبُ.","w":"القرطبي","en":"\"Adna\" means \"nearest\"."},{"bk":"al-muharrar-al-wajiz-ibn-atiyyah","s":30,"ay":3,"x":"و\"أدْنى الأرْضِ\" مَعْناهُ: أقْرَبُ الأرْضِ، فَإنْ كانَتِ الوَقْعَةُ في أذْرِعاتَ فَهي مِن أدْنى الأرْضِ بِالقِياسِ إلى مَكَّةَ، وهي الَّتِي ذَكَرَ امْرُؤُ القَيْسِ في قَوْلِهِ: ؎ تَنَوَّرْتُها مِن أذَرِعاتَ وأهْلُها ∗∗∗ بِيَثْرِبَ أدْنى دارِها نَظَرٌ عالِي وإنْ كانَتِ الوَقْعَةُ بِالجَزِيرَةِ فَهي أدْنى بِالقِياسِ إلى أرْضِ كِسْرى، وإنْ كانَتْ بِالأُرْدُنِّ فَهي أدْنى إلى أرْضِ الرُومِ …","w":"ابن عطية","en":"\"Adna al-ard\" means the nearest land: if the battle was at Adhri'at it is among the nearest land relative to Makkah, as Imru' al-Qays mentioned in his verse; if it was in the Jazirah it is nearest relative to Khosrow's land, and if in Jordan it is nearest to the land of Rome.","bt":"المحرر الوجيز لابن عطية"}],"h":[],"sci":"أخفض يابسة على سطح الأرض هي شاطئ البحر الميت، وهو أكثر من ٤٢٠ متراً تحت مستوى سطح البحر.","note":"قال القرطبي وابن عطية إن «أدنى» بمعنى أقرب، وإن المعركة كانت بأذرعات وبصرى (عكرمة)، وهي أدنى بالقياس إلى مكة، أو بالجزيرة (مجاهد) أو بالأردن (مقاتل). فتعيين المكان محل خلاف، ولا يُجزم بأن «أدنى» هنا بمعنى «أخفض».","refs":["Encyclopaedia Britannica، مادة «Dead Sea»."]},{"id":"ihtizaz","ch":"ard","t":"اهتزاز الأرض وربوها بالماء","e":"الآيتان في الأرض الهامدة إذا نزل عليها الماء فاهتزت وربت وأنبتت.","lv":"m","ay":[[22,5,5],[41,39,39]],"q":[{"bk":"qurtubi","s":22,"ay":5,"x":"قَوْلُهُ تَعَالَى: ﴿فَإِذا أَنْزَلْنا عَلَيْهَا الْماءَ اهْتَزَّتْ﴾ أَيْ تَحَرَّكَتْ.","w":"القرطبي","en":"\"And when We send down water upon it, it stirs\": that is, it moved."},{"bk":"tabari","s":22,"ay":5,"x":"وقوله ﴿فَإِذَا أَنزلْنَا عَلَيْهَا الْمَاءَ اهْتَزَّتْ﴾ يقول تعالى ذكره: فإذا نحن أنزلنا على هذه الأرض الهامدة التي لا نبات فيها، المطر من السماء اهتزّت يقول: تحركت بالنبات، ﴿وَرَبَتْ﴾ يقول: وأضعفت النبات بمجيء الغيث.","w":"الطبري","en":"His words \"when We send down water upon it, it stirs\": when We send rain from the sky onto this barren earth, in which there is no vegetation, it stirs, meaning it moves with growth, \"and swells\", meaning it multiplies its vegetation with the coming of the rain."},{"bk":"saadi","s":22,"ay":5,"x":"والدليل الثاني: إحياء الأرض بعد موتها، فقال الله فيه:{وترى الأرض هامدةً}؛ أي: خاشعة مغبرَّةً لا نباتَ فيها ولا خُضرة، {فإذا أنۡزَلۡنا عليها الماء اهتزَّتۡ}؛ أي: تحرَّكت بالنبات، {وَرَبَتۡ}؛ أي: ارتفعت بعد خُشوعها، وذلك لزيادة نباتها، {وأنبتتۡ من كلِّ زوج}؛ أي: صنف من أصناف النبات {بَهيج}؛ أي: يُبْهجُ الناظرين ويسرُّ المتأملين.","w":"السعدي","en":"The second proof is giving the earth life after its death. Allah said: \"and you see the earth barren\", that is, bowed down and dusty with no vegetation or greenness; \"when We send down water upon it, it stirs\", that is, it moves with growth, \"and swells\", that is, it rises after its humbleness through the increase of its vegetation, \"and brings forth of every pair\", that is, every kind of plant, \"delightful\", delighting the onlookers and pleasing those who reflect."}],"h":[],"sci":"إذا نزل المطر على تربة جافة هامدة تشرّبت جزيئات الطين الماء فانتفخت وتمددت، فيعلو سطح التربة وتتحرك حبيباتها، ثم تنبت البذور وتنمو نباتات من أصناف كثيرة.","note":"فسّر القرطبي «اهتزت» بتحركت، وقال الطبري والسعدي: تحركت بالنبات وربت أي ارتفعت وزاد نباتها. فالمعنى المأثور هو الحركة والارتفاع، والربط بتمدد التربة قراءة معاصرة مشهورة.","refs":["Taiz & Zeiger, Plant Physiology, Sinauer."]},{"id":"ayun","ch":"ard","t":"الماء يُسلك ينابيع في الأرض","e":"الآيتان في إنزال الماء من السماء وسلكه ينابيع في الأرض.","lv":"m","ay":[[39,21,21],[23,18,18]],"q":[{"bk":"ibnkathir","s":39,"ay":21,"x":"يُخْبِرُ تَعَالَى: أَنَّ أَصْلَ الْمَاءِ فِي الْأَرْضِ مِنَ السَّمَاءِ كَمَا قَالَ تَعَالَى: ﴿وَأَنزلْنَا مِنَ السَّمَاءِ مَاءً طَهُورًا﴾ [الْفُرْقَانِ:٤٨] ، فَإِذَا أَنْزَلَ الْمَاءَ مِنَ السَّمَاءِ كَمَن فِي الْأَرْضِ، ثُمَّ يَصْرِفُهُ تَعَالَى فِي أَجْزَاءِ الْأَرْضِ كَمَا يَشَاءُ، ويُنِبُعه عُيُونًا مَا بَيْنَ صِغَارٍ وَكِبَارٍ، بِحَسْبِ الْحَاجَةِ إِلَيْهَا؛ وَلِهَذَا قَالَ: ﴿فَسَلَكَهُ يَنَابِيعَ فِي الأرْضِ﴾ .","w":"ابن كثير","en":"Allah tells that the origin of the water in the earth is from the sky, as He said \"and We sent down from the sky pure water\" (al-Furqan 48); when He sends the water from the sky it settles in the earth, then He directs it through parts of the earth as He wills and makes it spring forth as sources, small and large, according to need; hence He said \"and made it travel as springs in the earth\"."},{"bk":"saadi","s":39,"ay":21,"x":"يُذَكِّرُ تعالى أولي الألباب ما أنزلَه من السماء من الماء، وأنَّه سلكه ينابيع في الأرض؛ أي: أودعه فيها ينبوعاً يُسْتَخْرَجُ بسهولةٍ ويسرٍ.","w":"السعدي","en":"He reminds those of understanding of the water He sent down from the sky and that He made it travel as springs in the earth; that is, He placed in it a spring that is drawn out easily and with ease."}],"h":[],"sci":"المياه الجوفية والينابيع تتغذى في معظمها بمياه الأمطار والثلوج الذائبة المتسربة إلى باطن الأرض، وقد قرر علم الهيدرولوجيا أن الدورة المائية مصدرها، وأوضح ذلك العلماء منذ القرن السابع عشر الميلادي (بيير بيرو، ١٦٧٤م).","note":"قال ابن كثير: أصل الماء في الأرض من السماء، ثم يصرفه تعالى في أجزاء الأرض ويُنبعه عيوناً. وقال السعدي: أودعه فيها ينبوعاً يُستخرج بسهولة. فالمعنى المأثور موافق للعلم، وليس في المأثور حديث عن تفاصيل الدورة المائية.","refs":["Pierre Perrault, De l'origine des fontaines (1674).","Oki & Kanae, «Global hydrological cycles and world water resources», Science 313 (2006)."]},{"id":"barzakh","ch":"bahr","t":"البرزخ بين البحرين","e":"الآيات في مرج البحرين: عذبٍ وملحٍ، وجعل برزخ بينهما.","lv":"m","ay":[[25,53,53],[55,19,20]],"q":[{"bk":"ibnkathir","s":25,"ay":53,"x":"وَقَوْلُهُ: ﴿وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا﴾ أَيْ: بَيْنَ الْعَذْبِ وَالْمَالِحِ ﴿بَرْزَخًا﴾ أَيْ: حَاجِزًا، وَهُوَ اليَبَس مِنَ الْأَرْضِ، ﴿وَحِجْرًا مَحْجُورًا﴾ أَيْ: مَانِعًا أَنْ يَصِلَ أَحَدُهُمَا إِلَى الْآخَرِ …","w":"ابن كثير","en":"\"And He placed between them a barrier and a forbidden partition\": between the sweet and the salty, a barrier, that is a divider, which is the dry land of the earth, \"and a forbidden partition\", that is, a hindrance preventing either from reaching the other."},{"bk":"saadi","s":55,"ay":19,"x":"المراد بالبحرين: البحر العذب والبحر المالح؛ فهما يلتقيان [كلاهما]، فيصبُّ العذب في البحر المالح ويختلطان ويمتزجان، ولكنَّ الله تعالى جعل بينهما برزخاً من الأرض، حتى لا يبغي أحدهما على الآخر، ويحصُلَ النفع بكلٍّ منهما؛ فالعذب منه يشربون وتشرب أشجارهم وزروعهم وحروثهم، والملح به يطيبُ الهواء ويتولَّد الحوت والسمك واللؤلؤ والمرجان …","w":"السعدي","en":"The two seas are the sweet sea and the salty sea; they meet, and the sweet pours into the salty and they mix and blend, but Allah placed between them a barrier of land, so that neither oversteps the other and benefit comes from each: from the sweet they drink and their trees, crops and fields drink, and by the salty the air is made pleasant and fish, pearls and coral are produced, and it is a stable thing made subservient to ships and vessels."},{"bk":"qurtubi","s":55,"ay":20,"x":"(بَيْنَهُما بَرْزَخٌ) أَيْ حَاجِزٌ فَعَلَى الْقَوْلِ الْأَوَّلِ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، قَالَهُ الضَّحَّاكُ.","w":"القرطبي","en":"\"Between them is a barrier\": that is, a divider; on the first view it is what is between the sky and the earth, said by al-Dahhak."}],"h":[],"sci":"عند التقاء مياه مختلفة في الملوحة والكثافة (كالنهر في البحر، أو مياه المتوسط ومياه الأطلسي عند مضيق جبل طارق) تتكوّن منطقة انتقالية رقيقة تُبقي كلاً من الكتلتين محتفظة بخصائصها مسافات طويلة، مع امتزاج تدريجي عبر هذا الحد.","note":"فسّر ابن كثير والسعدي البرزخ بحاجز من اليابس بين العذب والمالح، ونقل القرطبي عن الضحاك أنه ما بين السماء والأرض. فالمأثور يختلف عن الحاجز المائي الذي يصفه علم المحيطات، ولا يصح أن يُقال إن الماءين لا يمتزجان إطلاقاً، فعلم المحيطات يثبت امتزاجاً تدريجياً.","refs":["Pickard & Emery, Descriptive Physical Oceanography: An Introduction, Butterworth-Heinemann."]},{"id":"zulumat","ch":"bahr","t":"ظلمات البحر اللجي والموج","e":"الآية في ظلمات البحر اللجي وما يغشاه من موج وسحاب.","lv":"m","ay":[[24,40,40]],"q":[{"bk":"saadi","s":24,"ay":40,"x":"والمثل الثاني لبطلان أعمال الكفار: {كظُلُماتٍ في بحرٍ لُجِّيٍّ}: بعيدٍ قعرُهُ طويل مداهُ، {يغشاه موجٌ من فوقِهِ موجٌ من فوقِهِ سحابٌ ظلماتٌ بعضُها فوق بعض}: ظلمةُ البحر اللُّجِّيِّ، ثم فوقه ظلمة الأمواج المتراكمة، ثم فوق ذلك ظلمة السحب المدلهمَّة، ثم فوق ذلك ظلمةُ الليل البهيم، فاشتدَّت الظلمةُ جدًّا؛ بحيث أنَّ الكائن في تلك الحال {إذا أخرجَ يَدَه لم يكدۡ يراها}: مع قربِها إليه؛ فكيف بغيرها؟!","w":"السعدي","en":"The second parable for the falsity of the deeds of the unbelievers: \"or like darknesses in a deep sea\", whose bottom is far and extent long, \"covered by wave upon wave above it, above that a cloud, darknesses one above another\": the darkness of the deep sea, above it the darkness of piled waves, above that the darkness of heavy clouds, above that the darkness of the pitch-black night, so the darkness became intense, so that whoever is in that state \"if he puts out his hand, he can hardly see it\", though it is close to him; how then anything else?"},{"bk":"ibnkathir","s":24,"ay":40,"x":"﴿يَغْشَاهُ مَوْجٌ مِنْ فَوْقِهِ مَوْجٌ مِنْ فَوْقِهِ سَحَابٌ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا﴾ أَيْ: لَمْ يُقَارِبْ رُؤْيَتَهَا مِنْ شِدَّةِ الظَّلَامِ …","w":"ابن كثير","en":"\"Covered by wave upon wave above it, above that a cloud, darknesses one above another; if he puts out his hand he can hardly see it\": that is, he cannot nearly see it for the intensity of the darkness."}],"h":[],"sci":"يضعف الضوء مع العمق: يختفي الأحمر أولاً، ولا يكاد يصل ضوء الشمس بعد نحو ٢٠٠ متر، وتعمّ الظلمة التامة تحت نحو ألف متر؛ وتُرصد في المحيطات أمواج داخلية عند حدود الطبقات المختلفة الكثافة تحت السطح، فوقها أمواج السطح.","note":"عدّ السعدي الظلمات: ظلمة البحر ثم الأمواج ثم السحب ثم الليل، وقال ابن كثير إنها مثل لقلب الكافر الجاهل المقلّد. فالآية مثل في سياقها، والربط بعلم البحار قراءة معاصرة مشهورة، ولا يلزم أن تكون الأمواج الداخلية مقصودة.","refs":["Pickard & Emery, Descriptive Physical Oceanography: An Introduction, Butterworth-Heinemann."]},{"id":"sahab","ch":"bahr","t":"السحاب: يزجيه الله ثم يؤلف بينه ثم يجعله ركاماً","e":"الآية في سَوق السحاب وتأليفه وجعله ركاماً ثم نزول الودق منه.","lv":"z","ay":[[24,43,43]],"q":[{"bk":"saadi","s":24,"ay":43,"x":"أي: ألم تشاهدْ ببصرِك عظيمَ قدرةِ الله وكيف {يُزۡجي}؛ أي: يسوق {سحاباً}: قطعاً متفرقة، {ثم يؤلِّفُ}: بين تلك القطع، فيجعلُه سحاباً متراكماً مثل الجبال {فترى الوَدۡقَ}؛ أي: الوابل والمطر يخرجُ من خلال السحابِ نقطاً متفرِّقة؛ ليحصُلَ بها الانتفاع من دون ضررٍ، فتمتلئ بذلك الغُدران، وتتدفَّق الخُلجان، وتسيل الأوديةُ، وتنبتُ الأرض من كلِّ زوج كريم.","w":"السعدي","en":"That is: have you not seen with your own eyes the greatness of Allah's power and how He \"drives\" clouds, that is, impels them as scattered pieces, \"then joins\" those pieces and makes them piled-up cloud like mountains, \"and you see the rain\", that is, the downpour and the rain, coming out from among the clouds as scattered drops so that it benefits without harm, so the pools fill, the gulfs overflow, the valleys flow and the earth grows every noble pair."},{"bk":"qurtubi","s":24,"ay":43,"x":"(ثُمَّ يُؤَلِّفُ بَيْنَهُ) أَيْ يَجْمَعُهُ عِنْدَ انْتِشَائِهِ، لِيَقْوَى وَيَتَّصِلَ وَيَكْثُفَ.","w":"القرطبي","en":"\"Then He joins it together\": that is, He gathers it when it spreads, so that it grows strong, connects and thickens."}],"h":[],"sci":"تدفع الرياح سحباً صغيرة متفرقة فتتجمع وتلتحم بتيارات الحمل الحراري، ثم تتراكم رأسياً في سحابة ركامية مزنية ضخمة قد يبلغ ارتفاعها عدة كيلومترات، يخرج المطر من خلالها وقد يتكوّن منها البَرَد.","note":"فسّر السعدي «يزجي» بيسوق قطعاً متفرقة و«يؤلف» بالجمع بين القطع وجعلها سحاباً متراكماً مثل الجبال، وقال القرطبي: يجمعه ليقوى ويتصل ويكثف. فالمعنى المأثور ظاهر ويوافقه وصف الأرصاد الجوية.","refs":["Robert A. Houze, Cloud Dynamics, Academic Press."]},{"id":"lawaqih","ch":"bahr","t":"الرياح لواقح","e":"الآية في إرسال الرياح لواقح فينزل الماء من السماء.","lv":"z","ay":[[15,22,22]],"q":[{"bk":"ibnkathir","s":15,"ay":22,"x":"وَقَوْلُهُ: ﴿وَأَرْسَلْنَا الرِّيَاحَ لَوَاقِحَ﴾ أَيْ: تُلَقِّحُ السَّحَابَ فَتُدِرُّ مَاءً، وَتُلَقِّحُ الشَّجَرَ فَتَتَفَتَّحُ عَنْ أَوْرَاقِهَا وَأَكْمَامِهَا.","w":"ابن كثير","en":"And His words \"and We sent the winds fertilising\": that is, they fertilise the clouds so they give water, and they fertilise the trees so they open their leaves and blossoms."},{"bk":"tabari","s":15,"ay":22,"x":"والصواب من القول في ذلك عندي: أن الرياح لواقح كما وصفها به جلّ ثناؤه من صفتها، وإن كانت قد تلقح السحاب والأشجار، فهي لاقحة ملقحة، ولقحها: حملها الماء وإلقاحها السحاب والشجر: عملها فيه …","w":"الطبري","en":"The correct view in my opinion is that the winds are \"lawaqih\" as He described them; though they may fertilise clouds and trees, they are both conceiving and fertilising: their conceiving is their carrying water, and their fertilising of cloud and tree is their work in it."},{"bk":"qurtubi","s":15,"ay":22,"x":"وَمَعْنَى \"لَواقِحَ\" حَوَامِلَ، لِأَنَّهَا تَحْمِلُ الْمَاءَ وَالتُّرَابَ وَالسَّحَابَ وَالْخَيْرَ وَالنَّفْعَ.","w":"القرطبي","en":"The meaning of \"lawaqih\" is carriers, because they carry water, dust, clouds, good and benefit."}],"h":[],"sci":"تحمل الرياح حبوب اللقاح فتلقّح كثيراً من النباتات (كالنخيل والصنوبريات والحبوب)، كما تسهم في نقل بخار الماء وتجميع السحب فينزل المطر.","note":"نصّ ابن كثير على معنيين: تلقيح السحاب وتلقيح الشجر، وقال القرطبي: «لواقح» حوامل للماء والتراب والسحاب، ورجّح الطبري أنها لاقحة ملقِحة. وهي أقوال قديمة موافقة لما يقرره علم النبات والأرصاد، فالمعنى ظاهر.","refs":["Wallace & Hobbs, Atmospheric Science: An Introductory Survey, Academic Press.","Taiz & Zeiger, Plant Physiology, Sinauer."]},{"id":"matar","ch":"bahr","t":"المطر بقدر والسماء ذات الرجع","e":"الآيات في إنزال الماء بقدر وفي السماء ذات الرجع.","lv":"m","ay":[[23,18,18],[86,11,11],[43,11,11]],"q":[{"bk":"qurtubi","s":86,"ay":11,"x":"قَوْلُهُ تَعَالَى: ﴿وَالسَّماءِ ذاتِ الرَّجْعِ﴾ أَيْ ذَاتِ الْمَطَرِ.","w":"القرطبي","en":"His words \"by the sky that gives back\" means the one with rain."},{"bk":"ibnkathir","s":86,"ay":11,"x":"وَعَنْهُ: ﴿وَالسَّمَاءِ ذَاتِ الرَّجْعِ﴾ تُمْطِرُ ثُمَّ تُمْطِرُ.","w":"ابن كثير","en":"And from him: \"by the sky that gives back\": it rains and rains again."},{"bk":"qurtubi","s":23,"ay":18,"x":"الثَّانِيَةُ- قَوْلُهُ تَعَالَى: ﴿بِقَدَرٍ﴾ أَيْ عَلَى مِقْدَارٍ مُصْلِحٍ، لِأَنَّهُ لَوْ كَثُرَ أَهْلَكَ، وَمِنْهُ قَوْلُهُ تَعَالَى:\" وَإِنْ مِنْ شَيْءٍ إِلَّا عِنْدَنا خَزائِنُهُ وَما نُنَزِّلُهُ إِلَّا بِقَدَرٍ مَعْلُومٍ \" [الحجر: ٢١].","w":"القرطبي","en":"The second: His words \"bi-qadar\", that is, in a beneficial measure, for if it were much it would destroy; as His words \"and there is nothing but that its treasuries are with Us, and We send it down only in a known measure\" (al-Hijr 21)."}],"h":[],"sci":"الدورة المائية: يتبخر الماء من البحار والتربة والنبات، ثم يتكاثف في الجو ويعود مطراً أو ثلجاً؛ ويُقدَّر الهطول السنوي على الكرة الأرضية بنحو نصف مليون كيلومتر مكعب، تتوزع على المناطق بنسب تحفظ التوازن المائي.","note":"قال ابن عباس في «الرجع»: المطر، «تمطر ثم تمطر» (ابن كثير)، وهو قول أهل اللغة (القرطبي)، وفسّر القرطبي «بقدر» بمقدار مصلح لو كثر لأهلك. فالمعنى المأثور المطر وعودته، والربط بالدورة المائية ظاهر ومتّسق.","refs":["Oki & Kanae, «Global hydrological cycles and world water resources», Science 313 (2006)."]},{"id":"ma","ch":"bahr","t":"«وجعلنا من الماء كل شيء حي»","e":"الآية في جعل كل شيء حي من الماء.","lv":"z","ay":[[21,30,30],[24,45,45]],"q":[{"bk":"ibnkathir","s":21,"ay":30,"x":"وَقَوْلُهُ: ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾ أَيْ: أَصْلُ كل الأحياء منه.","w":"ابن كثير","en":"And His words \"and We made from water every living thing\": that is, the origin of all living things is from it."},{"bk":"qurtubi","s":21,"ay":30,"x":"الثَّانِي- حِفْظُ حَيَاةِ كل شي بِالْمَاءِ.","w":"القرطبي","en":"The second: the preservation of the life of everything by water."}],"h":[],"sci":"كل الكائنات الحية المعروفة تحتاج إلى الماء السائل، وأجسامها تتألف في معظمها منه (نحو ٦٠٪ من جسم الإنسان البالغ، وأكثر من ذلك في كثير من النباتات)، وتجري التفاعلات الحيوية في وسط مائي، ولا تُعرف حياة بلا ماء.","note":"قال ابن كثير: أصل كل الأحياء منه، وذكر القرطبي معنى حفظ حياة كل شيء بالماء. والمراد بـ«كل شيء حي» الأحياء، وهو الأقرب، ولا يُجزم بعموم أبعد.","refs":["Alberts et al., Molecular Biology of the Cell, Garland Science."]},{"id":"atwar","ch":"insan","t":"أطوار خلق الإنسان في الرحم","e":"الآيات في خلق الإنسان من سلالة من طين ثم نطفة فعلقة فمضغة فعظام تُكسى لحماً.","lv":"m","ay":[[23,12,14],[22,5,5],[40,67,67]],"q":[{"bk":"saadi","s":23,"ay":14,"x":"{ثم خلقنا النطفةَ}: التي قد استقرَّت قبل {علقةً}؛ أي: دماً أحمر بعد مضيِّ أربعين يوماً من النطفة، ثم {خلقنا العلقةَ}: بعد أربعين يوماً {مضغةً}؛ أي: قطعة لحم صغيرةٍ بقدر ما يُمْضَغ من صغرها، {فَخلۡقنا المضغة}: اللينةَ {عظاماً}: صلبةً قد تخلَّلت اللحم بحسب حاجة البدن إليها، {فكَسَوۡنا العظام لحماً}؛ أي: جعلنا اللحم كسوة للعظام؛ كما جعلنا العظام عماداً للحم …","w":"السعدي","en":"\"Then We made the drop\" which had settled, \"a clot\", that is red blood after forty days from the drop, then \"We made the clot\" after forty days \"a lump\", that is a small piece of flesh the size of what is chewed, \"then We made the lump\" the soft \"bones\", hard ones that run through the flesh according to the body's need of them, \"then We clothed the bones with flesh\", that is, We made the flesh a covering for the bones as We made the bones a support for the flesh …"},{"bk":"ibnkathir","s":23,"ay":14,"x":"﴿فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً﴾ : وَهِيَ قِطْعَةٌ كالبَضعة مِنَ اللَّحْمِ، لَا شَكْلَ فِيهَا وَلَا تَخْطِيطَ، ﴿فَخَلَقْنَا الْمُضْغَةَ عِظَامًا﴾ يَعْنِي: شَكَّلْنَاهَا ذَاتَ رَأْسٍ وَيَدَيْنِ وَرِجْلَيْنِ بِعِظَامِهَا وَعَصَبِهَا وَعُرُوقِهَا.","w":"ابن كثير","en":"\"Then We made the clot a lump\": a piece like a morsel of flesh, with no shape or outline; \"then We made the lump bones\", meaning We shaped it with a head, two hands and two feet, with its bones, nerves and vessels."},{"bk":"tabari","s":22,"ay":5,"x":"قال: ومعنى ذلك: فإنا خلقناكم من تراب، ثم من نطفة مخلَّقة وغير مخلقة قالوا: فأما المخلقة فما كان خلقا سَوِيّا وأما غير مخلقة، فما دفعته الأرحام، من النطف، وألقته قبل أن يكون خلقا.","w":"الطبري","en":"He said: the meaning is that We created you from dust, then from a drop formed and unformed; the formed is what was a complete creation, and the unformed is what the wombs expelled of drops and cast out before it became a creation."}],"h":[{"x":"إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ …","w":"البخاري","bt":"صحيح البخاري","no":"3208","en":"Each of you is gathered in his mother's belly for forty days, then he is a clot for the same period, then a lump for the same period …"}],"sci":"يصف علم الأجنة نشأة الإنسان من اتحاد الحيوان المنوي بالبويضة، ثم انغراس الجنين في جدار الرحم وتعلّقه به، ثم ظهور كتل بدئية (الجسيدات) في هيئة كتلة صغيرة، ثم تكوّن الغضاريف والعظام وتحيط بها العضلات، ثم تتشكل الأعضاء.","note":"قرر السعدي وابن كثير ترتيب الأطوار: نطفة فعلقة فمضغة فعظام فكسوتها لحماً، وبيّن الطبري معنى المخلّقة وغير المخلّقة. وينبّه بعض المتخصصين إلى أن تكوّن العظام وعضلاتها يجري في فترة متداخلة، فيُفهم الترتيب ترتيباً عاماً. أما الأربعينات في الحديث فتوقيف نبوي يُسلَّم به ولا تُطبَّق عليه أرقام علمية تطبيقاً جازماً.","refs":["Keith L. Moore, T. V. N. Persaud & M. Torchia, The Developing Human: Clinically Oriented Embryology, Elsevier."]},{"id":"amshaj","ch":"insan","t":"نطفة أمشاج","e":"الآية في خلق الإنسان من نطفة أمشاج.","lv":"z","ay":[[76,2,2]],"q":[{"bk":"ibnkathir","s":76,"ay":2,"x":"ثُمَّ بَيْنَ ذَلِكَ فَقَالَ: ﴿إِنَّا خَلَقْنَا الإنْسَانَ مِنْ نُطْفَةٍ أَمْشَاجٍ﴾ أَيْ: أَخْلَاطٍ.","w":"ابن كثير","en":"Then He explained that by saying: \"We created man from a mixed drop\", that is, mixtures."},{"bk":"ibnkathir","s":76,"ay":2,"x":"قَالَ ابْنُ عَبَّاسٍ فِي قَوْلِهِ: ﴿مِنْ نُطْفَةٍ أَمْشَاجٍ﴾ يَعْنِي: مَاءَ الرَّجُلِ وَمَاءَ الْمَرْأَةِ إِذَا اجْتَمَعَا وَاخْتَلَطَا، ثُمَّ يَنْتَقِلُ بَعْدُ مِنْ طَوْرٍ إِلَى طَوْرٍ، وَحَالٍ إِلَى حَالٍ، وَلَوْنٍ إِلَى لَوْنٍ.","w":"ابن كثير","en":"Ibn Abbas said of \"from a mixed drop\": the man's fluid and the woman's fluid when they come together and mix, then it moves on from stage to stage, state to state and colour to colour."},{"bk":"qurtubi","s":76,"ay":2,"x":"(أَمْشاجٍ): أَخْلَاطٌ.","w":"القرطبي","en":"\"Amshaj\" means mixtures."}],"h":[],"sci":"يتكوّن الجنين من اتحاد خليتين جنسيتين: حيوان منوي من الرجل وبويضة من المرأة، تمتزج مادتاهما الوراثية (٢٣ كروموسوماً من كل منهما فيصير للجنين ٤٦)، فتتكوّن النطفة المختلطة.","note":"فسّر ابن عباس ومجاهد وعكرمة والحسن «أمشاج» بامتزاج ماء الرجل بماء المرأة (ابن كثير)، وقال القرطبي: أخلاط. فالمعنى المأثور هو ما يقرره علم الوراثة نفسه، فالمعنى ظاهر.","refs":["Keith L. Moore, T. V. N. Persaud & M. Torchia, The Developing Human: Clinically Oriented Embryology, Elsevier."]},{"id":"thalath","ch":"insan","t":"الظلمات الثلاث","e":"الآية في خلقنا في بطون أمهاتنا خلقاً من بعد خلق في ظلمات ثلاث.","lv":"z","ay":[[39,6,6]],"q":[{"bk":"ibnkathir","s":39,"ay":6,"x":"وَقَوْلُهُ: ﴿فِي ظُلُمَاتٍ ثَلاثٍ﴾ يَعْنِي: ظُلْمَةَ الرَّحِمِ، وَظُلْمَةَ الْمَشِيمَةِ -الَّتِي هِيَ كَالْغِشَاوَةِ وَالْوِقَايَةِ عَلَى الْوَلَدِ -وَظُلْمَةَ الْبَطْنِ.","w":"ابن كثير","en":"And His words \"in three darknesses\": the darkness of the womb, the darkness of the placenta, which is like a covering and protection for the child, and the darkness of the belly."},{"bk":"tabari","s":39,"ay":6,"x":"وقوله: ﴿فِي ظُلُمَاتٍ ثَلاثٍ﴾ يعني: في ظلمة البطْن، وظلمة الرّحِم، وظُلْمة المَشِيمَة.","w":"الطبري","en":"And His words \"in three darknesses\" mean: in the darkness of the belly, the darkness of the womb and the darkness of the placenta."}],"h":[],"sci":"الجنين في الرحم محاط بثلاث طبقات واقية: جدار البطن، وجدار الرحم، والأغشية الجنينية (الأمنيوس والمشيمة) المحيطة به، ولا يصلها الضوء.","note":"فسّرها الطبري وابن كثير وغيرهما بظلمة البطن والرحم والمشيمة، فالمعنى منقول عنهم ويوافق ما يقرره علم التشريح.","refs":["Keith L. Moore, T. V. N. Persaud & M. Torchia, The Developing Human: Clinically Oriented Embryology, Elsevier."]},{"id":"sam","ch":"insan","t":"السمع قبل الأبصار","e":"الآيات في جعل السمع والأبصار والأفئدة.","lv":"x","ay":[[32,9,9],[76,2,2],[16,78,78]],"q":[{"bk":"tafsir-al-razi","s":32,"ay":9,"x":"المَسْألَةُ الثّانِيَةُ: التَّرْتِيبُ في السَّمْعِ والأبْصارِ والأفْئِدَةِ عَلى مُقْتَضى الحِكْمَةِ، وذَلِكَ لِأنَّ الإنْسانَ يَسْمَعُ أوَّلًا مِنَ الأبَوَيْنِ أوِ النّاسِ أُمُورًا فَيَفْهَمُها، ثُمَّ يَحْصُلُ لَهُ بِسَبَبِ ذَلِكَ بَصِيرَةٌ فَيُبْصِرُ الأُمُورَ ويُجَرِّبُها، ثُمَّ يَحْصُلُ لَهُ بِسَبَبِ ذَلِكَ إدْراكٌ تامٌّ وذِهْنٌ كامِلٌ فَيَسْتَخْرِجُ الأشْياءَ مِن قِبَلِهِ، ومِثالُهُ: شَخْصٌ يَسْمَعُ مِن أُسْتاذٍ شَيْئًا ثُمَّ يَصِيرُ لَهُ أهْلِيَّةُ مُطالَعَةِ الكُتُبِ وفَهْمِ مَعانِيها، ثُمَّ يَصِيرُ لَهُ أهْلِيَّةُ التَّصْنِيفِ فَيَكْتُبُ مِن قَلْبِهِ كِتابًا، فَكَذَلِكَ الإنْسانُ يَسْمَعُ ثُمَّ يُطالِعُ صَحائِفَ المَوْجُوداتِ ثُمَّ يَعْلَمُ الأُمُورَ الخَفِيَّةَ.","w":"الرازي","en":"The second point: the order of hearing, sight and hearts is according to wisdom, for a person first hears things from his parents or others and understands them, then through that he gains insight and sees things and tries them, then through that gains complete perception and a full mind and draws things out from within himself; an example is one who hears from a teacher, then becomes fit to read books and understand their meanings, then becomes fit to compose and writes a book from his heart; so a person hears, then reads the pages of existing things, then knows hidden matters.","bt":"مفاتيح الغيب (التفسير الكبير) للرازي"},{"bk":"saadi","s":32,"ay":9,"x":"{ثم سوَّاه} بلحمِهِ وأعضائِهِ وأعصابه وعروقِهِ، وأحسن خِلْقَتَه، ووضع كلَّ عضو منه بالمحلِّ الذي لا يليقُ به غيره، {ونفخ فيه من روحِهِ}: بأن أرسل إليه المَلَكَ؛ فينفخ فيه الروحَ، فيعود بإذن الله حيواناً بعد أن كان جماداً، {وجَعَلَ لكم السمعَ والأبصارَ}؛ أي: ما زال يعطيكم من المنافع شيئاً فشيئاً حتى أعطاكم السمع والأبصار {والأفئدة قليلاً ما تشكُرون}: الذي خلقكم، وصوَّركم.","w":"السعدي","en":"\"Then He fashioned him\" with his flesh, organs, nerves and vessels, and made his form beautiful, placing each organ where nothing else would fit; \"and breathed into him of His spirit\": by sending the angel to breathe the spirit into him, so he returns by Allah's leave a living being after being lifeless; \"and made for you hearing, sight\" meaning He kept giving you benefits little by little until He gave you hearing and sight, \"and hearts; little do you give thanks\": to the One who created and shaped you."}],"h":[],"sci":"يبدأ الجنين بالاستجابة للأصوات نحو الأسبوع الثامن عشر إلى العشرين من الحمل، بينما تبقى عيناه مغلقتين زمناً طويلاً ولا يتهيأ البصر للعمل إلا بعد الولادة بدرجة كبيرة.","note":"علّل الرازي ترتيب السمع قبل البصر بحكمة التعلّم: يسمع الإنسان أولاً ثم يبصر ثم يدرك بقلبه. فالترتيب عنده بلاغي تربوي، وربطه بنمو الحواس في الجنين اجتهاد لا يُجزم به.","refs":["Keith L. Moore, T. V. N. Persaud & M. Torchia, The Developing Human: Clinically Oriented Embryology, Elsevier."]},{"id":"dafiq","ch":"insan","t":"«من ماء دافق يخرج من بين الصلب والترائب»","e":"الآيات في خلق الإنسان من ماء دافق يخرج من بين الصلب والترائب.","lv":"x","ay":[[86,5,7]],"q":[{"bk":"ibnkathir","s":86,"ay":6,"x":"وَقَوْلُهُ: ﴿خُلِقَ مِنْ مَاءٍ دَافِقٍ﴾ يَعْنِي: الْمَنِيُّ؛ يَخْرُجُ دَفقًا مِنَ الرَّجُلِ وَمِنَ الْمَرْأَةِ، فَيَتَوَلَّدُ مِنْهُمَا الْوَلَدُ بِإِذْنِ اللَّهِ، عَزَّ وَجَلَّ ؛ وَلِهَذَا قَالَ: ﴿يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ﴾ يَعْنِي: صُلْبَ الرَّجُلِ وَتَرَائِبَ الْمَرْأَةِ، وَهُوَ صَدْرُهَا.","w":"ابن كثير","en":"And His words \"created from a gushing fluid\" mean semen; it comes out gushing from the man and from the woman, and from the two of them the child is born by Allah's leave; hence He said \"it comes from between the backbone and the ribs\", meaning the man's backbone and the woman's chest-bones, which is her chest."},{"bk":"qurtubi","s":86,"ay":7,"x":"قَالَ ابْنُ عَبَّاسٍ: التَّرَائِبُ: مَوْضِعُ الْقِلَادَةِ.","w":"القرطبي","en":"Ibn Abbas said: \"tara'ib\" is the place of the necklace."},{"bk":"qurtubi","s":86,"ay":7,"x":"وَعَنِ ابْنِ جُبَيْرٍ عَنِ ابْنِ عَبَّاسٍ: التَّرَائِبُ: أَرْبَعُ أَضْلَاعٍ مِنْ هَذَا الْجَانِبِ.","w":"القرطبي","en":"And from Ibn Jubayr from Ibn Abbas: \"tara'ib\" are four ribs on this side."}],"h":[],"sci":"تتكوّن الخصيتان والمبيضان في الجنين قرب الكليتين في منطقة الظهر ثم تهبطان إلى موضعيهما، وهو ما يربطه بعض الباحثين بقوله «من بين الصلب والترائب».","note":"اختلف المفسرون في «الترائب» اختلافاً واسعاً: موضع القلادة من الصدر، أو بين الثديين، أو أربعة أضلاع (القرطبي وابن كثير)، وفسّر ابن كثير الآية بصلب الرجل وترائب المرأة. فالربط الجنيني محل نقاش ولا يُجزم به.","refs":["Keith L. Moore, T. V. N. Persaud & M. Torchia, The Developing Human: Clinically Oriented Embryology, Elsevier."]},{"id":"dayq","ch":"insan","t":"ضيق الصدر عند الصعود في السماء","e":"الآية في أن من يرد الله أن يضله يجعل صدره ضيقاً حرجاً كأنما يصعد في السماء.","lv":"m","ay":[[6,125,125]],"q":[{"bk":"saadi","s":6,"ay":125,"x":"كأنه من ضيقه وشدَّته يكاد {يَصَّعَّدُ في السماء}؛ أي: كأنه يكلَّف الصعود إلى السماء الذي لا حيلة فيه …","w":"السعدي","en":"It is as though, from his tightness and intensity, he almost \"climbs into the sky\", that is, as if he were made to ascend to the sky with no way to do it …"},{"bk":"qurtubi","s":6,"ay":125,"x":"شَبَّهَ اللَّهُ الْكَافِرَ فِي نُفُورِهِ مِنَ الْإِيمَانِ وَثِقَلِهِ عَلَيْهِ بِمَنْزِلَةِ مَنْ تَكَلَّفَ مَا لَا يُطِيقُهُ، كَمَا أَنَّ صُعُودَ السَّمَاءِ لَا يُطَاقُ.","w":"القرطبي","en":"Allah likened the unbeliever in his aversion to faith and its heaviness on him to one who undertakes what he cannot bear, just as climbing to the sky cannot be borne."}],"h":[],"sci":"كلما ارتفع الإنسان عن مستوى البحر قلّ الضغط الجوي والأكسجين المتاح، فيتسارع النفس ويضيق الصدر ويحدث ما يُعرف بداء المرتفعات، وقد تشتد أعراضه فوق نحو ثلاثة آلاف متر.","note":"الآية تشبّه ضيق صدر من أُضلّ بمن يكلَّف الصعود إلى السماء (السعدي والقرطبي)، فهي تشبيه معنوي في سياق الهداية والإضلال. والتنبيه إلى الحقيقة الفسيولوجية استئناس لا تفسير.","refs":["John B. West, High Life: A History of High-Altitude Physiology and Medicine, Oxford University Press (1998).","Peacock, «ABC of oxygen: Oxygen at high altitude», BMJ 317 (1998)."]},{"id":"banan","ch":"insan","t":"تسوية البنان","e":"الآيتان في قدرته تعالى على جمع العظام وتسوية البنان.","lv":"x","ay":[[75,3,4]],"q":[{"bk":"qurtubi","s":75,"ay":4,"x":"وَقَالَ ابْنُ عَبَّاسٍ وَعَامَّةُ الْمُفَسِّرِينَ: الْمَعْنَى عَلى أَنْ نُسَوِّيَ بَنانَهُ أَيْ نَجْعَلَ أَصَابِعَ يَدَيْهِ وَرِجْلَيْهِ شَيْئًا وَاحِدًا كَخُفِّ الْبَعِيرِ، أَوْ كَحَافِرِ الْحِمَارِ، أَوْ كَظِلْفِ الْخِنْزِيرِ، وَلَا يُمْكِنُهُ أَنْ يَعْمَلَ بِهِ شَيْئًا، وَلَكِنَّا فَرَّقْنَا أَصَابِعَهُ حَتَّى يَأْخُذَ بِهَا مَا شَاءَ.","w":"القرطبي","en":"Ibn Abbas and most exegetes said: the meaning of \"that We fashion his fingertips\" is that We make the fingers of his hands and feet one piece, like a camel's hoof, a donkey's hoof or a pig's cloven foot, so he could do nothing with it; but We separated his fingers so he can take with them what he wishes."},{"bk":"ibnkathir","s":75,"ay":4,"x":"بَلَى سَنَجْمَعُهَا قَادِرِينَ عَلَى أَنْ نُسَوِّي بَنَانَهُ، أَيْ: قُدْرَتُنَا صَالِحَةٌ لِجَمْعِهَا، ولو شئنا لبعثناه أزيد مما كان، فتجعل بَنَانَهُ -وَهِيَ أَطْرَافُ أَصَابِعِهِ-مُسْتَوِيَةً.","w":"ابن كثير","en":"Rather We will gather them, able to fashion his fingertips, that is, Our power is fit to gather them, and had We willed We would have raised him greater than he was, making his fingertips, the ends of his fingers, level."}],"h":[],"sci":"بصمات الأصابع فريدة عند كل إنسان بما في ذلك التوأم المتطابق، وتتكوّن في الجنين قبل الولادة وتبقى ثابتة مدى الحياة، ولهذا اعتُمدت في تحقيق الشخصية.","note":"فسّر ابن عباس وعامة المفسرين «بنانه» بأصابع اليد والرجل: قادرون على أن نجعلها كخفّ البعير (القرطبي وابن كثير)، والسياق في البعث. فالربط بالبصمة قراءة معاصرة لا يُجزم بها.","refs":["Maltoni, Maio, Jain & Prabhakar, Handbook of Fingerprint Recognition, Springer."]},{"id":"nahl","ch":"ahya","t":"النحل: وحيها وبيوتها وشرابها","e":"الآيتان في وحي الله إلى النحل أن تتخذ بيوتاً وتأكل من الثمرات ويخرج من بطونها شراب فيه شفاء.","lv":"m","ay":[[16,68,69]],"q":[{"bk":"qurtubi","s":16,"ay":68,"x":"وَالنَّحْلُ يُؤَنَّثُ فِي لُغَةِ أَهْلِ الْحِجَازِ، وَكُلُّ جَمْعٍ لَيْسَ بَيْنَهُ وَبَيْنَ وَاحِدِهِ إِلَّا الْهَاءُ.","w":"القرطبي","en":"\"Nahl\" is feminine in the dialect of the people of the Hijaz, as with every collective noun that differs from its singular only by the \"ha\"."},{"bk":"ibnkathir","s":16,"ay":68,"x":"الْمُرَادُ بِالْوَحْيِ هَاهُنَا: الْإِلْهَامُ وَالْهِدَايَةُ وَالْإِرْشَادُ إِلَى النَّحْلِ أَنْ تَتَّخِذَ مِنَ الْجِبَالِ بُيُوتًا تَأْوِي إِلَيْهَا، وَمِنَ الشَّجَرِ، وَمِمَّا يَعْرِشُونَ.","w":"ابن كثير","en":"The inspiration here means instinct, guidance and direction to the bee to take houses from the mountains, from the trees and from what they build."},{"bk":"saadi","s":16,"ay":68,"x":"في خلق هذه النَّحلة الصغيرة، التي هداها الله هذه الهداية العجيبة، ويَسَّر لها المراعي، ثم الرجوع إلى بيوتها التي أصلحتها بتعليم الله لها وهدايته لها، ثم يخرج من بطونها هذا العسل اللذيذ مختلف الألوان بحسب اختلاف أرضها ومراعيها؛ فيه شفاء للناس من أمراض عديدة؛ فهذا دليلٌ على كمال عناية الله تعالى وتمام لطفه بعباده، وأنَّه الذي لا ينبغي أن يُحَبَّ غيره، ويُدْعى سواه.","w":"السعدي","en":"In the creation of this small bee, which Allah guided with this wonderful guidance, easing its pastures for it, then its return to its homes which it set right by Allah's teaching and guidance, then this delicious honey of differing colours according to its land and pastures comes out of its belly, in which is healing for people from many ailments; this is evidence of the perfection of Allah's care and the fullness of His gentleness to His servants, and that no other should be loved or called upon besides Him."}],"h":[],"sci":"العاملات في خلية النحل إناث عقيمات، وهنّ اللواتي يخرجن لجمع الرحيق وحبوب اللقاح ويبنين الشمع، أما الذكور فلا تعمل في الخلية؛ وتحوّل العاملات الرحيق إلى عسل في بطونها بإنزيمات خاصة.","note":"جاءت الأفعال بالمؤنث (اتخذي، كلي، فاسلكي)، وقال القرطبي: النحل يؤنث في لغة أهل الحجاز، فالتأنيث جارٍ على القاعدة اللغوية، ولا يُجزم بقصد الآية إلى جنس العاملات. وفسّر ابن كثير الوحي بالإلهام والهداية، وبيّن السعدي أن العسل فيه شفاء للناس.","refs":["Mark L. Winston, The Biology of the Honey Bee, Harvard University Press (1987)."]},{"id":"zawj","ch":"ahya","t":"الزوجية في الخلق","e":"الآيات في أن الله خلق من كل شيء زوجين، ومن الأرض ومن الأنفس وما لا يعلمون.","lv":"m","ay":[[51,49,49],[36,36,36],[13,3,3]],"q":[{"bk":"ibnkathir","s":51,"ay":49,"x":"﴿وَمِنْ كُلِّ شَيْءٍ خَلَقْنَا زَوْجَيْنِ﴾ أَيْ: جَمِيعُ الْمَخْلُوقَاتِ أَزْوَاجٌ: سَمَاءٌ وَأَرْضٌ، وَلَيْلٌ وَنَهَارٌ، وَشَمْسٌ وَقَمَرٌ، وَبَرٌّ وَبَحْرٌ، وَضِيَاءٌ وَظَلَامٌ، وَإِيمَانٌ وَكُفْرٌ، وَمَوْتٌ وَحَيَاةٌ، وَشَقَاءٌ وَسَعَادَةٌ، وَجَنَّةٌ وَنَارٌ، حَتَّى الْحَيَوَانَاتُ [جِنٌّ وَإِنْسٌ، ذُكُورٌ وَإِنَاثٌ] وَالنَّبَاتَاتُ، وَلِهَذَا قَالَ: ﴿لَعَلَّكُمْ تَذَكَّرُونَ﴾ أَيْ: لِتَعْلَمُوا أَنَّ الْخَالِقَ واحدٌ لَا شَرِيكَ لَهُ.","w":"ابن كثير","en":"\"And of everything We created two kinds\": all creatures are pairs: sky and earth, night and day, sun and moon, land and sea, light and dark, faith and disbelief, death and life, misery and happiness, paradise and hell, even animals, jinn and humans, males and females, and plants; hence He said \"that you may remember\", that is, to know that the Creator is One with no partner."},{"bk":"saadi","s":51,"ay":49,"x":"{ومن كلِّ شيءٍ خَلَقۡنا زوجين}؛ أي: صنفين ذكرٍ وأنثى من كلِّ نوع من أنواع الحيوانات، {لعلَّكم تذكَّرونَ}: لنعم اللهِ التي أنعم بها عليكم في تقدير ذلك وحكمتِهِ؛ حيث جعل ما هو السبب لبقاء نوع الحيوانات كلها؛ لتقوموا بتنميتها وخدمتها وتربيتها فيحصل من ذلك ما يحصل من المنافع.","w":"السعدي","en":"\"And of everything We created two kinds\", that is, two types, male and female, of every kind of animal, \"that you may remember\" the favours Allah has given you in decreeing this and its wisdom, for He made the cause of the survival of the species of all animals so that you can breed, serve and raise them and gain the benefits."},{"bk":"saadi","s":36,"ay":36,"x":"{سبحانَ الذي خَلَقَ الأزواجَ كُلَّها}؛ أي: الأصناف كلَّها {مما تُنۡبِتُ الأرضُ}: فَنَوَّعَ فيها من الأصناف ما يعسُرُ تعدادُهُ، {ومن أنفسِهِم}: فنوَّعَهم إلى ذكرٍ وأنثى، وفاوتَ بين خَلْقِهِم وخُلُقِهِم وأوصافهم الظاهرة والباطنة {وممَّا لا يعلمونَ}: من المخلوقات التي قد خُلِقَتْ وغابتْ عن عِلْمِنا، والتي لم تُخْلَقْ بعد؛ فسُبحانه وتعالى أن يكونَ له شريكٌ أو ظهيرٌ أو عوينٌ أو وزيرٌ أو صاحبةٌ أو ولدٌ أو سميٌّ أو شبيهٌ أو مثيلٌ في صفاتِ كماله ونعوتِ جلالِهِ، أو يُعْجِزَه شيءٌ يريدُه.","w":"السعدي","en":"\"Glory be to Him who created all the pairs\", that is, all the kinds, \"of what the earth grows\", varying in it kinds that are hard to count, \"and of themselves\", varying them into male and female and differing in their make, character and outward and inward qualities, \"and of what they do not know\": of creatures already made that are hidden from our knowledge, and of those not yet created; glory be to Him, exalted above having any partner, helper, aide, minister, consort, child, namesake, likeness or equal in His perfect attributes and majestic names, or being made powerless by anything He wills."}],"h":[],"sci":"الزوجية ظاهرة في الأحياء: الذكر والأنثى في الحيوان، وكثير من النبات له أعضاء مذكرة ومؤنثة؛ وفي المادة: لكل جسيم نقيض (الإلكترون والبوزيترون)، وفي الكهرباء شحنات موجبة وسالبة.","note":"فسّر ابن كثير «زوجين» بأزواج متقابلة: سماء وأرض، وليل ونهار، وشمس وقمر، وإيمان وكفر، وحتى الحيوان والنبات، وفسّره السعدي بالذكر والأنثى من الحيوان، وزاد في آية يس «وما لا يعلمون». فالمعنى أوسع من التزاوج الحيوي، والربط بنظام الجسيمات ونحوه اجتهاد.","refs":["Alberts et al., Molecular Biology of the Cell, Garland Science.","Mark L. Winston, The Biology of the Honey Bee, Harvard University Press (1987)."]}],"ay":{"913":"فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ","1368":"هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ","1709":"وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ","1823":"وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ","1968":"وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ","1969":"ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","1978":"وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ","2512":"أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ","2513":"وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ","2514":"وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ","2515":"وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ","2599":"يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ","2684":"وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ","2685":"ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ","2686":"ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ","2690":"وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ","2830":"أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن فَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ","2833":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي سَحَابٗا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٖ فِيهَا مِنۢ بَرَدٖ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ","2835":"وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","2907":"۞ وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا وَحِجۡرٗا مَّحۡجُورٗا","3410":"غُلِبَتِ ٱلرُّومُ","3411":"فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ","3412":"فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ","3511":"ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ","3740":"سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ","3742":"وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرّٖ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ","3744":"لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلّٞ فِي فَلَكٖ يَسۡبَحُونَ","4062":"خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ","4063":"خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ خَلۡقٗا مِّنۢ بَعۡدِ خَلۡقٖ فِي ظُلُمَٰتٖ ثَلَٰثٖۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ","4078":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ يُخۡرِجُ بِهِۦ زَرۡعٗا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ","4199":"هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ يُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى وَلَعَلَّكُمۡ تَعۡقِلُونَ","4228":"ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ","4256":"وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","4335":"وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ","4721":"وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ","4723":"وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ","4905":"ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانٖ","4919":"مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ","4920":"بَيۡنَهُمَا بَرۡزَخٞ لَّا يَبۡغِيَانِ","5099":"لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ","5433":"أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا","5434":"وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا","5553":"أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ","5554":"بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ","5592":"إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا","5677":"أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا","5678":"وَٱلۡجِبَالَ أَوۡتَادٗا","5935":"فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ","5936":"خُلِقَ مِن مَّآءٖ دَافِقٖ","5937":"يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ","5941":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ"},"nay":55,"nq":72};
